  `hero_id` int NOT NULL,
  `rank_id` int NOT NULL,
  `map_id` int NOT NULL,
  `win_rate` float NOT NULL,
  `date_of_the_data` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`hero_id`,`rank_id`,`map_id`,`date_of_the_data`),
