  CONSTRAINT `fk_map_win` FOREIGN KEY (`map_id`) REFERENCES `map` (`map_id`),
  CONSTRAINT `fk_rank_win` FOREIGN KEY (`rank_id`) REFERENCES `rank` (`rank_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
